let structuredData = {
    "contents": [
        {
            "heading": "overview",
            "content": "Workspace in Fumadocs MDX, refers to an independent project with its own config and content."
        },
        {
            "heading": "overview",
            "content": "title: Good to Know"
        },
        {
            "heading": "overview",
            "content": "Fumadocs MDX Workspace is not limited to the traditional meaning of workspace\nin package managers."
        },
        {
            "heading": "overview",
            "content": "They do not need to have its own package.json, only a config file is needed."
        },
        {
            "heading": "overview",
            "content": "To define a workspace, add:"
        },
        {
            "heading": "overview",
            "content": "import { defineConfig } from 'fumadocs-mdx/config';\n\nexport default defineConfig({\n  workspaces: {\n    'my-workspace': {\n      dir: 'my-workspace',\n      config: await import('./my-workspace/source.config.ts'),\n    },\n  },\n});"
        },
        {
            "heading": "overview",
            "content": "When writing content in a workspace, note that:"
        },
        {
            "heading": "overview",
            "content": "cwd refers to the current workspace directory."
        },
        {
            "heading": "overview",
            "content": "configs will not inherit, workspaces are always independent."
        },
        {
            "heading": "overview",
            "content": "By running dev or build server, you should see collection entries from all workspaces to be generated."
        },
        {
            "heading": "accessing-collections",
            "content": "You can access the generated files of a workspace at .source/{workspace}/*. For example:"
        },
        {
            "heading": "accessing-collections",
            "content": "import { docs } from 'fumadocs-mdx:collections/my-workspace/server';"
        },
        {
            "heading": "accessing-collections",
            "content": "The output location of root workspace is not changed."
        },
        {
            "heading": "accessing-collections",
            "content": "To integrate multiple sources in Fumadocs, use multiple:"
        },
        {
            "heading": "accessing-collections",
            "content": "import { loader, multiple } from 'fumadocs-core/source';\nimport { docs } from 'fumadocs-mdx:collections/server';\nimport * as MyWorkspace from 'fumadocs-mdx:collections/my-workspace/server';\n\nexport const source = loader(\n  multiple({\n    root: docs.toFumadocsSource(),\n    'my-workspace': MyWorkspace.docs.toFumadocsSource(),\n  }),\n  {\n    baseUrl: '/docs',\n  },\n);"
        },
        {
            "heading": "when-to-use",
            "content": "In some setups, you might have multiple Fumadocs MDX configs with their own content directory."
        },
        {
            "heading": "when-to-use",
            "content": "With workspaces, you can integrate them into one Fumadocs MDX config, and access all collections of each workspace."
        },
        {
            "heading": "when-to-use",
            "content": "This is crucial for use cases like storing content across multiple repos, a simplified setup would be:"
        },
        {
            "heading": "when-to-use",
            "content": "let your main docs repo be A, and other repos be T_n"
        },
        {
            "heading": "when-to-use",
            "content": "for each repo T_n:"
        },
        {
            "heading": "when-to-use",
            "content": "T_n has A as a git submodule."
        },
        {
            "heading": "when-to-use",
            "content": "T_n defines its own config source.config.ts and work independently."
        },
        {
            "heading": "when-to-use",
            "content": "when a commit is made to the content in T_n, it triggers a GitHub action (or CI), which creates a new deployment on A."
        },
        {
            "heading": "when-to-use",
            "content": "when a deployment is triggered on A:"
        },
        {
            "heading": "when-to-use",
            "content": "Fumadocs MDX handles each T_n as a workspace."
        },
        {
            "heading": "when-to-use",
            "content": "each workspace generates its own collection entries, e.g. fumadocs-mdx:collections/{repo}/server."
        },
        {
            "heading": "when-to-use",
            "content": "Fumadocs loader() integrate multiple sources into one."
        }
    ],
    "headings": [
        {
            "id": "overview",
            "content": "Overview"
        },
        {
            "id": "accessing-collections",
            "content": "Accessing Collections"
        },
        {
            "id": "when-to-use",
            "content": "When to Use"
        }
    ]
};
